cargo init --name keyed_totals -q . 2>&1; cat > src/main.rs <<'EOF'
use std::collections::HashMap;
use std::io::{self, BufWriter, Write};

/// Running state of one key: a total, or `None` once it has overflowed.
type Total = Option<i64>;

fn main() -> io::Result<()> {
    let path = std::env::args_os().nth(1).expect("usage: keyed_totals <file>");
    let data = std::fs::read(path)?;

    let mut lines: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
    if lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }
    let split = lines.iter().position(|l| l.is_empty()).unwrap_or(lines.len());
    let (records, rest) = lines.split_at(split);
    let queries = rest.get(1..).unwrap_or(&[]);

    let mut totals: HashMap<&[u8], Total> = HashMap::new();
    for line in records {
        let Some(sp) = line.iter().position(|&b| b == b' ') else {
            continue;
        };
        let (key, value) = (&line[..sp], &line[sp + 1..]);
        let Some(value) = std::str::from_utf8(value)
            .ok()
            .and_then(|s| s.trim().parse::<i64>().ok())
        else {
            continue;
        };
        let entry = totals.entry(key).or_insert(Some(0));
        *entry = entry.and_then(|t| t.checked_add(value));
    }

    let mut out = BufWriter::new(io::stdout().lock());
    for key in queries {
        out.write_all(key)?;
        match totals.get(key) {
            None => out.write_all(b"=absent\n")?,
            Some(None) => out.write_all(b"=overflow\n")?,
            Some(Some(t)) => writeln!(out, "={t}")?,
        }
    }
    out.flush()
}
